import {languages,text,nameFor} from './i18n.js';
import {KEY,APP_VERSION,MEASUREMENT_METHOD,MAX_SAMPLES,readState,validatePlan,completion,exportCsv,exportMeasurements,mergeBackup} from './model.js';
import {PoseEngine} from './pose-engine.js';
import {PoseVoiceGuide} from './pose-voice.js';
import {cameraConstraints,cameraInfo,setCameraZoom} from './camera-controls.js';
import {POSE_ASSETS} from './pose-assets.js';
const POSE_BYTES=POSE_ASSETS.flatMap(a=>a.chunks).reduce((n,c)=>n+c.size,0);
let storage;try{storage=localStorage}catch{storage={getItem:()=>null,setItem:()=>{throw Error()}}}
let state=readState(storage),view='today',filter='all',session=state.draft?{...state.draft,tick:performance.now()}:null,stream=null,cameraPending=false,cameraEpoch=0;
let cameraFacing='user',cameraMirrored=true,cameraDevices=[],activeDevice='',cameraZoom=null,zoomBusy=false,cameraHistory=false;
let poseEngine=null,poseEnabled=false,poseStatus='poseIdle',latestPose={left:null,right:null},cameraView='unmarked',lastSampleAt=-Infinity,poseProgress={loaded:0,total:POSE_BYTES,stage:'idle'},poseDiagnostic='';
const root=document.querySelector('#app'),modal=document.querySelector('#modal');
const t=k=>text(state.lang,k),name=id=>nameFor(state.lang,id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const voiceGuide=new PoseVoiceGuide({getLanguage:()=>state.lang,getText:t,enabled:state.voiceEnabled!==false,onChange:()=>updateVoiceControls()});
const icon=(k,size=20)=>{const paths={voice:'M3 9h4l5-4v14l-5-4H3zM16 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14',today:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-8h6v8',library:'M4 4h6v16H4zM14 4h6v16h-6z',train:'m9 5 11 7-11 7z',records:'M5 3h14v18H5zM8 8h8M8 12h8M8 16h5',settings:'M4 7h16M4 17h16M9 4v6M15 14v6',arrow:'M4 12h16m-6-6 6 6-6 6',camera:'M3 7h5l2-3h4l2 3h5v14H3zM15 13a3 3 0 1 1-6 0 3 3 0 0 1 6 0',check:'m5 12 4 4L19 6',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',plus:'M12 5v14M5 12h14',pause:'M8 5v14M16 5v14',close:'m6 6 12 12M6 18 18 6',leaf:'M20 3C9 2 2 6 5 15c10 4 15-3 15-12ZM4 21 15 10'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]||paths.leaf}"/></svg>`};
function pose(id=0,hero=false){const arms=['M110 104Q68 80 80 37M110 104q42-24 30-67','M110 104 57 92 38 73M110 104l48-22 28 10','M110 104 83 72 90 32M110 104l40 19 18-7','M110 104 79 121 69 110M110 104l36 15 10-10','M110 104 70 132M110 104l48 28','M110 104 87 142 76 168M110 104l27 38 9 26','M110 104 75 89 54 104M110 104l40 10 28-12','M110 104 81 131M110 104l30 27'];return `<svg class="pose ${hero?'hero-pose':''}" viewBox="0 0 220 240" aria-hidden="true"><ellipse cx="110" cy="222" rx="57" ry="5" fill="currentColor" opacity=".09"/><circle cx="110" cy="68" r="15" fill="currentColor"/><path d="M104 82q-10 9-13 23l-7 46q26 13 52 0l-7-46q-3-14-13-23" fill="currentColor" opacity=".88"/><path d="M90 153 79 196 67 217M130 153l12 43 15 21" stroke="currentColor" stroke-width="15" fill="none" stroke-linecap="round"/><path d="${arms[id]}" stroke="currentColor" stroke-width="12" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="m94 116 30 0" stroke="#f4f0e5" stroke-width="3" opacity=".6"/></svg>`}
function landscape(){return `<svg class="landscape" viewBox="0 0 620 360" aria-hidden="true"><circle cx="350" cy="150" r="122" fill="none" stroke="#c9be9e" stroke-width="1"/><circle cx="350" cy="150" r="112" fill="none" stroke="#c9be9e" opacity=".45"/><path d="M0 310 95 232 152 265 220 185 322 298 405 235 490 306 620 225V360H0" fill="#c1c6b6" opacity=".35"/><path d="m0 340 140-67 95 38 85-52 106 66 91-30 103 40v25H0" fill="#8e9e8e" opacity=".2"/><path d="M0 347q170-28 310 0t310 0" fill="none" stroke="#8a9d8b" opacity=".35"/></svg>`}
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('show'),3500)}
function persist(){try{storage.setItem(KEY,JSON.stringify(state));return true}catch{notify(t('storageError'));return false}}
function saveDraft(){state.draft=session?{...session,elapsed:Math.min(seconds(),86400),running:false}:null;if(state.draft)delete state.draft.tick;return persist()}
function updatePosePanel(){
 for(const status of document.querySelectorAll('#pose-status,#stage-status'))if(status.textContent!==t(poseStatus))status.textContent=t(poseStatus);
 for(const side of ['left','right']){const el=document.querySelector(`#angle-${side}`);if(el)el.textContent=latestPose[side]===null?'—':`${latestPose[side].toFixed(1)}°`}
 const failed=['poseFailed','poseDownloadFailed'].includes(poseStatus),buttons=document.querySelectorAll('[data-action="pose"]');for(const b of buttons){b.disabled=!stream;b.textContent=t(poseEnabled?'poseDisable':failed?'poseRetry':'poseEnable')}
 for(const reset of document.querySelectorAll('[data-action="reset-pose"]'))reset.disabled=!stream||!poseEnabled;
 const guide=document.querySelector('.camera-guide');if(guide)guide.hidden=poseEnabled;
 for(const progress of document.querySelectorAll('#pose-progress,#stage-progress')){progress.hidden=!poseEnabled||!['poseLoading','poseRetrying','poseInitialising'].includes(poseStatus);const percent=Math.min(100,Math.round(100*poseProgress.loaded/poseProgress.total));progress.querySelector('progress').value=percent;progress.querySelector('span').textContent=poseStatus==='poseInitialising'?t('poseInitialising'):`${t(poseProgress.stage==='retry'?'poseRetrying':'poseDownloading')} · ${(poseProgress.loaded/1048576).toFixed(1)} / ${(poseProgress.total/1048576).toFixed(1)} MB (${percent}%)${poseProgress.cached>0?' · '+t('poseFromCache')+' '+(poseProgress.cached/1048576).toFixed(1)+' MB':''}`}
 const hint=document.querySelector('#pose-cache-hint');if(hint)hint.textContent=t(poseProgress.cacheAvailable===false?'poseNoCache':'poseCacheHint');
 const d=document.querySelector('#pose-diagnostics');if(d){d.hidden=!poseDiagnostic;d.querySelector('code').textContent=poseDiagnostic}
}
async function togglePose(){if(poseEnabled){stopPose();updatePosePanel();return}if(!stream)return;if(typeof WebAssembly==='undefined'){poseStatus='poseFailed';poseDiagnostic='WebAssembly is unavailable in this browser.';updatePosePanel();return}voiceGuide.activate();poseEnabled=true;poseStatus='poseLoading';poseProgress={loaded:0,total:POSE_BYTES,stage:'download'};poseDiagnostic='';latestPose={left:null,right:null};const epoch=cameraEpoch;poseEngine=new PoseEngine({onProgress:p=>{poseProgress=p;updatePosePanel()},onDiagnostic:message=>{poseDiagnostic=message;updatePosePanel()},getContext:()=>session?.running?{sessionId:session.id,at:new Date().toISOString(),elapsed:Math.min(seconds(),86400),moveId:session.plan[session.index].id,view:cameraView}:null,onStatus:status=>{poseStatus=status;if(['poseFailed','poseDownloadFailed','poseNoFrames'].includes(status))latestPose={left:null,right:null};if(['poseFailed','poseDownloadFailed'].includes(status)){poseEnabled=false;voiceGuide.stop()}else voiceGuide.observe(status,{left:latestPose.left,right:latestPose.right,view:cameraView});updatePosePanel()},onResult:result=>{latestPose=result;updatePosePanel();const now=performance.now();if(session?.running&&result.context?.sessionId===session.id&&now-lastSampleAt>=1000&&session.samples.length<MAX_SAMPLES){lastSampleAt=now;session.samples.push({at:result.context.at,elapsed:result.context.elapsed,moveId:result.context.moveId,view:result.context.view,method:MEASUREMENT_METHOD,width:result.width,height:result.height,left:result.left,right:result.right})}}});poseEngine.attach(document.querySelector('#camera-video'),document.querySelector('#pose-canvas'),{mirrored:cameraMirrored});updatePosePanel();try{await poseEngine.start()}catch(error){if(epoch===cameraEpoch&&poseEnabled){poseEnabled=false;poseStatus='poseFailed';poseDiagnostic=String(error?.message||error);updatePosePanel()}}}
function stopPose(){voiceGuide.stop();poseEngine?.stop();poseEngine=null;poseEnabled=false;poseStatus='poseIdle';latestPose={left:null,right:null};poseProgress={loaded:0,total:POSE_BYTES,stage:'idle'};poseDiagnostic=''}
function langSelect(){return `<select aria-label="${t('language')}" class="language-select" data-change="language">${[['zh','简体中文'],['yue','繁體粵語'],['en','English']].map(([v,l])=>`<option value="${v}" ${state.lang===v?'selected':''}>${l}</option>`).join('')}</select>`}
function date(s,short=false){return new Intl.DateTimeFormat(state.lang==='en'?'en-GB':state.lang==='yue'?'zh-HK':'zh-CN',{month:short?'numeric':'short',day:'numeric',...(short?{}:{year:'numeric'})}).format(new Date(s))}
function time(seconds){return `${Math.floor(seconds/60).toString().padStart(2,'0')}:${Math.floor(seconds%60).toString().padStart(2,'0')}`}
function seconds(){return session?session.elapsed+(session.running?Math.max(0,Math.floor((performance.now()-session.tick)/1000)):0):0}
function nav(v){if(['train','camera'].includes(view)&&v!==view){pauseSession();stopCamera()}view=v;render();window.scrollTo({top:0,behavior:'instant'})}
function layout(content){return `<aside class="sidebar"><a class="brand" href="#" data-action="nav" data-view="today"><span class="brand-mark">${state.lang==='zh'?'锦':'錦'}</span><span><strong>${t('brand')}</strong><small>JINMOTION</small></span></a><div class="nav-caption">BADUANJIN / 八段錦</div><nav aria-label="${t('navLabel')}">${['today','library','train','records'].map(v=>`<button class="nav-item ${view===v?'selected':''}" data-action="nav" data-view="${v}" ${view===v?'aria-current="page"':''}>${icon(v)}<span>${t(v)}</span>${v===view?'<i></i>':''}</button>`).join('')}</nav><div class="side-bottom"><div class="seal-small">八<br>段<br>錦</div><p>${t('footer')}</p><button class="nav-item ${view==='settings'?'selected':''}" data-action="nav" data-view="settings">${icon('settings')}<span>${t('settings')}</span></button><span class="version">JINMOTION · ${APP_VERSION}</span></div></aside><div class="workspace"><header class="topbar"><div><span class="mobile-brand">${t('brand')}</span><span class="top-label">${t('subbrand')}</span></div><div class="top-controls"><span class="prototype-pill"><span></span>${t('prototype')}</span>${langSelect()}<button class="icon-button mobile-settings" data-action="nav" data-view="settings" aria-label="${t('settings')}">${icon('settings')}</button></div></header><main>${content}<footer>${icon('leaf',16)}<span>${t('footer')}</span></footer></main></div>`}
function painControl(key,value){return `<label class="range-label" for="${key}">${t(key==='pre'?'painBefore':'painAfter')}<output id="${key}-value">${value}<small> / 10</small></output></label><input type="range" id="${key}" min="0" max="10" step="1" value="${value}" data-input="${key}" aria-describedby="${key}-hint"><div class="range-ends" id="${key}-hint"><span>${t('painHint')}</span></div>`}
function checkin(){return `<section class="card checkin"><span class="eyebrow">CHECK IN</span><h2>${t('checkin')}</h2><p class="muted">${t('nextNote')}</p>${painControl('pre',state.pre)}<div class="local-line">${icon('lock',15)}${t('localNote')}</div></section>`}
function planRows(plan=state.plan){return plan.map((m,i)=>`<div class="plan-row"><span class="move-thumb tone-${m.id%3}">${pose(m.id)}</span><span class="move-number">${String(i+1).padStart(2,'0')}</span><div class="plan-name"><strong>${name(m.id)}</strong><small>BADUANJIN · ${String(m.id+1).padStart(2,'0')}</small></div><span class="rep-label">${m.reps}<small> ${t('reps')}</small></span></div>`).join('')}
function statCards(){const logs=state.logs,week=logs.filter(l=>Date.now()-new Date(l.endedAt).getTime()<7*86400000),last=logs.at(-1);return `<div class="stats"><div class="stat">${icon('leaf')}<div><span>${t('weekSessions')}</span><strong>${week.length}<small>${t('sessions')}</small></strong></div></div><div class="stat">${icon('clock')}<div><span>${t('totalTime')}</span><strong>${Math.round(logs.reduce((n,l)=>n+l.seconds,0)/60)}<small>${t('minutes')}</small></strong></div></div><div class="stat"><span class="pain-icon">◉</span><div><span>${t('lastPain')}</span><strong>${last?last.post:'—'}<small>${last?'/ 10':t('noData')}</small></strong></div></div></div>`}
function logCard(l){return `<article class="log-row"><div class="date-square"><strong>${new Date(l.endedAt).getDate()}</strong><small>${new Intl.DateTimeFormat(state.lang==='en'?'en-GB':'zh-HK',{month:'short'}).format(new Date(l.endedAt))}</small></div><div class="log-main"><strong>${l.plan.length} ${t('moves')} <span class="tag ${l.status==='stopped'?'warm':''}">${t(l.status==='stopped'?'stopped':'completed')}</span></strong><p>${t('elapsed')} ${time(l.seconds)} · ${t('completion')} ${l.completion}%</p><small>${t('painBefore')} ${l.pre}/10 → ${t('painAfter')} ${l.post}/10</small>${l.samples?.length?`<p class="measurement-badge">${t('measurements')} ${l.samples.length} · ${t('samplesHint')}</p>`:''}${l.note?`<p class="record-note">${esc(l.note)}</p>`:''}</div><button class="text-button danger" data-action="delete-log" data-id="${esc(l.id)}">${t('delete')}</button></article>`}
function empty(){return `<div class="empty">${icon('leaf',32)}<h3>${t('emptyTitle')}</h3><p>${t('emptyText')}</p></div>`}
function creatorCredit(){return `<section class="creator-credit" aria-label="${t('creatorsTitle')}"><div class="creator-heading"><span>HKBU</span><div><h2>${t('creatorsTitle')}</h2><p>${t('creatorsInstitution')}</p></div></div><div class="creator-names"><p>${t('creatorProfessor')}</p><p>${t('creatorCandidate')}</p></div></section>`}
function today(){return `<div class="page-kicker">${date(new Date())}<span> / </span>${t('greeting')}</div><section class="hero"><div class="hero-content"><div class="eyebrow">THE EIGHT BROCADES</div><h1>${t('heroTitle').replace('\n','<br>')}</h1><p>${t('heroText')}</p><div class="hero-actions"><button class="primary" data-action="nav" data-view="train">${session?t('resume'):t('start')}${icon('arrow')}</button><button class="text-button" data-action="nav" data-view="library">${t('explore')}</button></div></div><div class="hero-art">${landscape()}${pose(0,true)}<div class="red-seal">八<br>段<br>錦</div><span class="art-caption">呼 吸 · 開 合</span></div></section>${creatorCredit()}${statCards()}<div class="dashboard-grid"><section class="card plan-card"><div class="section-head"><div><span class="eyebrow">YOUR PRACTICE</span><h2>${t('todayPlan')}</h2></div><button class="text-button" data-action="edit-plan">${t('editPlan')} ↗</button></div><p class="small muted plan-caption">${t(state.custom?'manualPlan':'example')} · ${state.plan.length} ${t('moves')}</p>${planRows()}</section>${checkin()}</div><section class="card recent"><div class="section-head"><h2>${t('recent')}</h2><button class="text-button" data-action="nav" data-view="records">${t('viewAll')} ↗</button></div>${state.logs.length?logCard(state.logs.at(-1)):empty()}</section><p class="prototype-note">${t('prototypeNote')}</p>`}
function library(){const ids=Array.from({length:8},(_,i)=>i).filter(id=>filter==='all'||state.plan.some(m=>m.id===id));return `<div class="page-intro"><span class="eyebrow">THE MOVEMENT COLLECTION</span><h1>${t('libraryTitle')}</h1><p>${t('libraryText')}</p></div><div class="library-toolbar"><div class="segmented"><button class="${filter==='all'?'on':''}" data-action="filter" data-filter="all">${t('allMoves')}</button><button class="${filter==='selected'?'on':''}" data-action="filter" data-filter="selected">${t('selected')}</button></div><button class="outline" data-action="edit-plan">${t('editPlan')}</button></div><div class="movement-grid">${ids.map(id=>`<article class="movement-card"><button class="movement-art tone-${id%3}" data-action="detail" data-id="${id}" aria-label="${esc(name(id))}"><span class="art-number">${String(id+1).padStart(2,'0')}</span><span class="art-orbit"></span>${pose(id)}${state.plan.some(m=>m.id===id)?`<span class="in-plan">${icon('check',13)}${t('selected')}</span>`:''}</button><div class="movement-info"><h2>${name(id)}</h2><button class="text-button" data-action="detail" data-id="${id}">${t('details')} ${icon('arrow',16)}</button></div></article>`).join('')}</div>`}
function feedbackChoice(){return `<h3>${t('feedback')}</h3><div class="segmented feedback-options">${['realtime','summary'].map(f=>`<button data-action="feedback" data-value="${f}" class="${state.feedback===f?'on':''}">${t(f)}</button>`).join('')}</div><p class="small muted">${t('feedbackHint')}</p>`}
function voiceSettings(){return `<section class="voice-settings"><div class="section-head"><h3>${t('voiceTitle')}</h3><button class="text-button" data-action="voice-toggle" aria-pressed="${state.voiceEnabled!==false}">${t(state.voiceEnabled!==false?'voiceOn':'voiceOff')}</button></div><p class="small muted">${t('voiceLanguage')}</p><p class="small muted" data-voice-availability></p><button class="text-button" data-action="voice-test">${t('voiceTest')}</button></section>`}
function updateVoiceControls(){const availability=voiceGuide.availability,enabled=state.voiceEnabled!==false,key={ready:'voiceHelp',unsupported:'voiceUnsupported',loading:'voiceLoading',missing:'voiceMissing',blocked:'voiceBlocked'}[availability];for(const button of document.querySelectorAll('[data-action="voice-toggle"]')){button.setAttribute('aria-pressed',String(enabled));button.setAttribute('aria-label',t(enabled?'voiceOn':'voiceOff'));button.title=t(enabled?'voiceOn':'voiceOff');button.disabled=availability==='unsupported';if(!button.hasAttribute('data-voice-icon'))button.textContent=t(enabled?'voiceOn':'voiceOff');button.classList.toggle('voice-muted',!enabled||availability!=='ready')}for(const button of document.querySelectorAll('[data-action="voice-test"]'))button.disabled=availability==='unsupported';for(const label of document.querySelectorAll('[data-voice-availability]'))label.textContent=t(key);const note=document.querySelector('#stage-voice-note');if(note){note.hidden=!enabled||!['missing','blocked','unsupported'].includes(availability);note.textContent=t(key)}}
function poseControls(){return `<div class="pose-lab">${voiceSettings()}<div class="section-head"><h3>${t('poseTitle')}</h3><span class="tag warm">LAB</span></div><label class="camera-view-label" for="camera-view">${t('cameraView')}</label><select id="camera-view" data-change="camera-view">${['unmarked','front','leftSide','rightSide'].map(v=>`<option value="${v}" ${v===cameraView?'selected':''}>${t(v)}</option>`).join('')}</select><button class="outline full" data-action="pose" ${stream?'':'disabled'}>${t(poseEnabled?'poseDisable':'poseEnable')}</button><button class="text-button full" data-action="reset-pose" ${poseEnabled?'':'disabled'}>${t('poseReset')}</button><p id="pose-status" class="small muted" role="status">${t(poseStatus)}</p><div id="pose-progress" class="pose-progress" hidden><progress max="100" value="0" aria-label="${t('poseDownloading')}"></progress><span></span></div><p id="pose-cache-hint" class="small muted">${t('poseCacheHint')}</p><p class="small muted">${t('poseSetupHint')}</p><details id="pose-diagnostics" hidden><summary>${t('poseDiagnostics')}</summary><code></code></details><div class="angle-readings"><div><span>${t('leftKnee')}</span><strong id="angle-left">${latestPose.left===null?'—':latestPose.left.toFixed(1)+'°'}</strong></div><div><span>${t('rightKnee')}</span><strong id="angle-right">${latestPose.right===null?'—':latestPose.right.toFixed(1)+'°'}</strong></div></div><p class="small muted pose-disclaimer">${t('poseHint')}</p><p class="small muted">${t('posePrivacy')}</p><p class="small muted">${t('poseRecording')}</p></div>`}
function cameraPanel(){return `<section class="card camera-card"><div class="section-head"><h2>${t('camera')}</h2>${icon('camera')}</div><p class="small muted camera-instructions">${t('poseOverlayHint')}</p><div class="camera-screen" data-mirrored="${cameraMirrored}"><video id="camera-video" autoplay playsinline muted ${stream?'':'hidden'}></video><canvas id="pose-canvas" aria-hidden="true"></canvas><div id="camera-placeholder" ${stream?'hidden':''}>${icon('camera',34)}<p>${t('cameraHint')}</p></div><span class="camera-guide" ${poseEnabled?'hidden':''}></span></div><button class="outline full" data-action="camera">${t(stream?'cameraStop':'cameraOff')}</button><p class="small muted">${t('cameraPrivate')}</p>${cameraOptions()}${poseControls()}</section>`}
function train(){if(!session)return `<div class="page-intro"><span class="eyebrow">PRACTICE WITH INTENTION</span><h1>${t('practiceTitle')}</h1><p>${t('practiceText')}</p></div><div class="practice-grid"><div><section class="card ready-card"><div class="section-head"><h2>${t('ready')}</h2><button class="text-button" data-action="edit-plan">${t('editPlan')} ↗</button></div><p class="muted">${t('readyText')}</p>${planRows()}<div class="pre-session">${painControl('pre',state.pre)}</div><button class="primary full" data-action="begin">${t('start')}${icon('arrow')}</button></section></div><div>${cameraPanel()}<section class="card feedback-card">${feedbackChoice()}</section></div></div>`;
 const m=session.plan[session.index],count=session.counts[session.index];return `<div class="page-intro compact"><span class="eyebrow">YOUR MOMENT OF MOVEMENT</span><h1>${t('train')}</h1></div><div class="practice-grid"><section class="card active-practice"><div class="session-top"><span class="tag ${session.running?'':'warm'}" id="session-status">${t(session.running?'active':'paused')}</span><span class="timer" id="timer">${time(seconds())}</span></div><div class="active-art tone-${m.id%3}"><span class="art-orbit"></span>${pose(m.id)}<small>${t('artNote')}</small></div><div class="session-caption"><span class="eyebrow">${session.index+1} / ${session.plan.length}</span><h2>${name(m.id)}</h2><div class="counter"><strong>${count}</strong><span>/ ${m.reps} ${t('reps')}</span></div></div><progress value="${completion(session.counts,session.plan)}" max="100" aria-label="${t('completion')}"></progress><div class="counter-controls"><button class="outline" data-action="undo" ${!count||!session.running?'disabled':''} aria-label="${t('undoRep')}">−</button><button class="primary" data-action="rep" ${count>=m.reps||!session.running?'disabled':''}>${t('addRep')}</button><button class="outline" data-action="pause">${icon(session.running?'pause':'train')}${t(session.running?'pause':'resume')}</button></div><div class="session-bottom"><button class="text-button" data-action="end">${t('endEarly')}</button><button class="text-button" data-action="next">${t(session.index===session.plan.length-1?'finish':'nextMove')}${icon('arrow',16)}</button></div></section><div>${cameraPanel()}<section class="card"><h3>${t('todayPlan')}</h3><div class="session-steps">${session.plan.map((x,i)=>`<div class="session-step ${i===session.index?'current':''}"><span>${session.counts[i]===x.reps?icon('check',16):String(i+1).padStart(2,'0')}</span><p>${name(x.id)}</p><small>${session.counts[i]} / ${x.reps}</small></div>`).join('')}</div></section></div></div>`}
function chart(){const logs=state.logs.slice(-7);if(logs.length<2)return `<div class="chart-empty">${icon('records',28)}<p>${t('trendEmpty')}</p></div>`;const w=680,h=195,x=i=>45+i*(600/(logs.length-1)),y=v=>155-v*12;return `<div class="chart-legend"><span><i></i>${t('painBefore')}</span><span><i></i>${t('painAfter')}</span></div><svg class="trend-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${t('trend')}">${[0,5,10].map(v=>`<line x1="35" y1="${y(v)}" x2="655" y2="${y(v)}" stroke="#e4e5dc"/><text x="10" y="${y(v)+4}">${v}</text>`).join('')}${['pre','post'].map((k,j)=>`<polyline points="${logs.map((l,i)=>`${x(i)},${y(l[k])}`).join(' ')}" fill="none" stroke="${j?'#b3664e':'#456455'}" stroke-width="2.5"/>${logs.map((l,i)=>`<circle cx="${x(i)}" cy="${y(l[k])}" r="4" fill="${j?'#b3664e':'#456455'}"/><text x="${x(i)}" y="${y(l[k])+(j?17:-10)}" text-anchor="middle">${l[k]}</text>`).join('')}`).join('')}${logs.map((l,i)=>`<text x="${x(i)}" y="185" text-anchor="middle">${date(l.endedAt,true)}</text>`).join('')}</svg>`}
function records(){return `<div class="page-intro"><span class="eyebrow">A JOURNAL OF YOUR PRACTICE</span><h1>${t('journalTitle')}</h1><p>${t('journalText')}</p></div>${statCards()}<section class="card"><div class="section-head"><h2>${t('trend')}</h2><button class="outline" data-action="export-csv">${icon('download',16)}${t('export')}</button></div>${chart()}</section><div class="measurement-export"><button class="text-button" data-action="export-measurements">${icon('download',16)}${t('exportAngles')}</button><span>${t('samplesHint')}</span></div><section class="card recent"><div class="section-head"><h2>${t('allRecords')}</h2><span class="muted small">${state.logs.length} ${t('sessions')}</span></div>${state.logs.length?[...state.logs].reverse().map(logCard).join(''):empty()}</section>`}
function settings(){return `<div class="page-intro"><span class="eyebrow">YOUR SPACE</span><h1>${t('settingsTitle')}</h1></div><div class="settings-grid"><section class="card"><h2>${t('language')}</h2><p class="muted">${t('languageHint')}</p>${langSelect()}</section><section class="card">${feedbackChoice()}</section><section class="card"><div class="section-head"><h2>${t('privacyTitle')}</h2>${icon('lock')}</div><p class="muted">${t('privacyText')}</p><div class="button-row"><button class="outline" data-action="export-json">${icon('download',16)}${t('exportJson')}</button><button class="text-button" data-action="export-csv">${t('export')}</button><button class="outline" data-action="import-json">${t('importJson')}</button><input type="file" accept="application/json,.json" id="backup-file" hidden></div><p class="small muted">${t('importHint')}</p></section><section class="card"><h2>${t('install')}</h2><p class="muted">${t('installText')}</p></section><section class="card about-card"><span class="eyebrow">JINMOTION · ${APP_VERSION}</span><h2>${t('about')}</h2><p class="muted">${t('aboutText')}</p><p class="prototype-note">${t('prototypeNote')}</p></section></div>`}
function render(){const previousVideo=stream?document.querySelector('#camera-video'):null;document.documentElement.lang={zh:'zh-CN',yue:'yue-HK',en:'en'}[state.lang];document.title=state.lang==='en'?'JinMotion':`${t('brand')} · JinMotion`;root.innerHTML=view==='camera'?cameraStage():layout(({today,library,train,records,settings}[view])());document.body.classList.toggle('camera-open',view==='camera');if(session&&(view==='today'||view==='train')){const banner=document.createElement('div');banner.className='draft-banner';banner.innerHTML=`${icon('check',16)}<span>${t('draftSaved')}<small>${t('draftHint')}</small></span>`;root.querySelector('main').prepend(banner)}if(stream){let v=document.querySelector('#camera-video');if(v){if(previousVideo){v.replaceWith(previousVideo);v=previousVideo}v.hidden=false;if(v.srcObject!==stream)v.srcObject=stream;v.play().catch(()=>{poseStatus='poseNoFrames';updatePosePanel()});poseEngine?.attach(v,document.querySelector('#pose-canvas'),{mirrored:cameraMirrored})}}updatePosePanel();updateVoiceControls()}
function pauseSession(){if(session?.running){session.elapsed=Math.min(seconds(),86400);session.running=false;saveDraft()}}
function stopCamera(){cameraEpoch++;cameraPending=false;stopPose();if(stream){stream.getTracks().forEach(x=>x.stop());stream=null}}
function enterCamera(){if(view!=='camera'){view='camera';try{window.history.pushState({jinmotionCamera:true},'', '#camera');cameraHistory=true}catch{}}}
function exitCamera(){pauseSession();stopCamera();view='train';render();if(cameraHistory){cameraHistory=false;window.history.back()}}
function cameraStage(){return `<main class="camera-stage" aria-label="${t('cameraPractice')}"><div class="camera-screen" data-mirrored="${cameraMirrored}"><video id="camera-video" autoplay playsinline muted ${stream?'':'hidden'}></video><canvas id="pose-canvas" aria-hidden="true"></canvas><div id="camera-placeholder" ${stream?'hidden':''}>${icon('camera',40)}<p>${t(cameraPending?'cameraLoading':'cameraHint')}</p>${!cameraPending?`<button class="outline" data-action="camera">${t('cameraOff')}</button>`:''}</div></div><header class="camera-stage-header"><button class="stage-icon" data-action="camera-exit" aria-label="${t('cameraBack')}">←</button><span>${session?name(session.plan[session.index].id):t('cameraPractice')}</span><button class="stage-icon stage-voice" data-action="voice-toggle" data-voice-icon aria-label="${t(state.voiceEnabled!==false?'voiceOn':'voiceOff')}" aria-pressed="${state.voiceEnabled!==false}">${icon('voice')}</button><details class="camera-drawer"><summary aria-label="${t('cameraLens')}">${icon('settings')}</summary><div class="camera-drawer-content"><h2>${t('cameraLens')}</h2>${cameraOptions()}${poseControls()}</div></details></header><div class="camera-stage-status"><p id="stage-status" role="status">${t(poseStatus)}</p><p id="stage-voice-note" hidden></p><div id="stage-progress" class="pose-progress" hidden><progress max="100" value="0" aria-label="${t('poseDownloading')}"></progress><span></span></div></div><div class="camera-stage-footer">${session?`<div class="stage-session"><span id="timer">${time(seconds())}</span><span>${session.counts[session.index]} / ${session.plan[session.index].reps}</span><button data-action="rep" ${!session.running||session.counts[session.index]>=session.plan[session.index].reps?'disabled':''}>+1</button><button data-action="pause" aria-label="${t(session.running?'pause':'resume')}">${icon(session.running?'pause':'train')}</button><button data-action="next">${t(session.index===session.plan.length-1?'finish':'nextMove')}</button></div>`:`<button class="stage-begin" data-action="begin">${t('start')}</button>`}<div class="stage-buttons"><button data-action="pose" ${stream?'':'disabled'}>${t(poseEnabled?'poseDisable':'poseEnable')}</button><button data-action="reset-pose" aria-label="${t('poseReset')}" ${poseEnabled?'':'disabled'}>${t('poseResetShort')}</button><button data-action="switch-camera" aria-label="${t(cameraFacing==='user'?'cameraUseRear':'cameraUseFront')}" ${cameraPending?'disabled':''}>${icon('camera')} ${t('cameraFlip')}</button></div></div></main>`}
function cameraOptions(){if(!stream)return '';return `<div class="camera-options"><div class="section-head"><span>${t('cameraLens')}</span><button class="text-button" data-action="switch-camera" ${cameraPending?'disabled':''}>${t(cameraFacing==='user'?'cameraUseRear':'cameraUseFront')}</button></div>${cameraDevices.length>1?`<label for="camera-device">${t('cameraChoose')}</label><select id="camera-device" data-change="camera-device">${cameraDevices.map((d,i)=>`<option value="${esc(d.deviceId)}" ${d.deviceId===activeDevice?'selected':''}>${esc(d.label||t('cameraLens')+' '+(i+1))}</option>`).join('')}</select>`:''}${cameraZoom?`<label class="range-label" for="camera-zoom">${t('cameraZoom')}<output id="camera-zoom-value">${cameraZoom.value.toFixed(1)}×</output></label><input id="camera-zoom" type="range" min="${cameraZoom.min}" max="${cameraZoom.max}" step="${cameraZoom.step}" value="${cameraZoom.value}" data-change="camera-zoom"><button class="text-button" data-action="camera-wide">${t('cameraWidest')}</button>`:`<p class="small muted">${t('cameraNoZoom')}</p>`}<p class="small muted">${t('cameraPositionHint')}</p></div>`}
async function startCamera({facing=cameraFacing,deviceId=''}={}){
 if(cameraPending)return;const resumeTracking=poseEnabled;enterCamera();const epoch=++cameraEpoch;cameraPending=true;stopPose();if(stream){stream.getTracks().forEach(x=>x.stop());stream=null}cameraZoom=null;render();notify(t('cameraLoading'));
 try{if(!navigator.mediaDevices?.getUserMedia)throw Error();const next=await navigator.mediaDevices.getUserMedia(cameraConstraints({facing,deviceId}));if(epoch!==cameraEpoch||view!=='camera'){next.getTracks().forEach(x=>x.stop());return}
  const track=next.getVideoTracks()[0];let info=cameraInfo(track);if(info.zoom){try{await setCameraZoom(track,info.zoom.min);info=cameraInfo(track)}catch{}}
  let devices=[];try{devices=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='videoinput')}catch{}
  if(epoch!==cameraEpoch||view!=='camera'){next.getTracks().forEach(x=>x.stop());return}stream=next;cameraFacing=info.facing||facing;cameraMirrored=cameraFacing==='user';activeDevice=info.deviceId||deviceId;cameraDevices=devices;cameraZoom=info.zoom;render();notify(t('cameraActive'));
 }catch{if(epoch===cameraEpoch)notify(t('cameraError'))}finally{if(epoch===cameraEpoch){cameraPending=false;render();if(resumeTracking&&stream)void togglePose()}}
}
async function toggleCamera(){if(stream){stopCamera();render();return}await startCamera()}
async function changeZoom(value){if(zoomBusy||!stream)return;zoomBusy=true;try{await setCameraZoom(stream.getVideoTracks()[0],value);cameraZoom=cameraInfo(stream.getVideoTracks()[0]).zoom;if(poseEngine)poseEngine.quality=new (await import('./pose-quality.js')).PoseQuality()}catch{notify(t('cameraZoomFailed'))}finally{zoomBusy=false;const input=document.querySelector('#camera-zoom'),label=document.querySelector('#camera-zoom-value');if(cameraZoom&&input){input.value=cameraZoom.value;label.textContent=cameraZoom.value.toFixed(1)+'×'}}}
function openModal(body){if(modal.open)modal.close();modal.innerHTML=`<button class="modal-close icon-button" data-action="close" aria-label="${t('close')}">${icon('close')}</button>${body}`;modal.showModal()}
function editPlan(){if(session){notify(t('planLocked'));return}openModal(`<form id="plan-form"><span class="eyebrow">YOUR PRACTICE</span><h2>${t('planTitle')}</h2><p class="muted">${t('planHelp')}</p><div class="plan-editor">${Array.from({length:8},(_,id)=>{const m=state.plan.find(x=>x.id===id);return `<div><label class="check-label"><input type="checkbox" name="move-${id}" ${m?'checked':''}>${name(id)}</label><label class="rep-input"><input type="number" name="reps-${id}" value="${m?.reps??6}" min="1" max="30" step="1" required aria-label="${esc(name(id)+' '+t('reps'))}"><span>${t('reps')}</span></label></div>`}).join('')}</div><p class="form-error" id="plan-error" role="alert"></p><div class="modal-actions"><button type="button" class="outline" data-action="close">${t('cancel')}</button><button class="primary" type="submit">${t('save')}</button></div></form>`)}
function detail(id){const inPlan=state.plan.some(m=>m.id===id);openModal(`<div class="detail-art tone-${id%3}">${pose(id)}</div><span class="eyebrow">BADUANJIN · ${String(id+1).padStart(2,'0')}</span><h2>${name(id)}</h2><p class="small muted">${t('artNote')}</p><div class="pending-label">${t('evidencePending')}</div><p class="muted">${t('movementNote')}</p><button class="primary full" data-action="toggle-move" data-id="${id}">${t(inPlan?'removePlan':'addPlan')}</button>`)}
function finishDialog(){if(!session)return;pauseSession();stopCamera();if(view==='camera')view='train';render();openModal(`<form id="session-form"><span class="eyebrow">REFLECT & RECORD</span><h2>${t('saveSession')}</h2><div class="session-summary"><span>${t('elapsed')} <strong>${time(seconds())}</strong></span><span>${t('completion')} <strong>${completion(session.counts,session.plan)}%</strong></span></div>${painControl('post',session.post??session.pre)}<label class="range-label" for="effort">${t('effort')}<output id="effort-value">${session.effort??0}<small> / 10</small></output></label><input type="range" id="effort" name="effort" min="0" max="10" value="${session.effort??0}" data-input="effort"><p class="small muted">${t('effortHint')}</p><label class="note-label" for="session-note">${t('note')}</label><textarea id="session-note" name="note" rows="3" maxlength="1000" placeholder="${t('notePlaceholder')}" data-input="session-note">${esc(session.note??'')}</textarea><div class="modal-actions"><button class="outline" type="button" data-action="close">${t('cancel')}</button><button class="primary" type="submit">${t('save')}</button></div></form>`)}
function download(content,type,extension){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=`jinmotion-${new Date().toISOString().slice(0,10)}.${extension}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notify(t('exported'))}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id);if(b.tagName==='A')e.preventDefault();switch(a){case'nav':nav(b.dataset.view);break;case'filter':filter=b.dataset.filter;render();break;case'edit-plan':editPlan();break;case'close':modal.close();break;case'detail':detail(id);break;case'toggle-move':{if(session){notify(t('planLocked'));break}const exists=state.plan.some(m=>m.id===id);if(exists&&state.plan.length===1){notify(t('needMove'));break}state.plan=exists?state.plan.filter(m=>m.id!==id):[...state.plan,{id,reps:6}].sort((a,b)=>a.id-b.id);state.custom=true;persist();modal.close();render();break}case'feedback':state.feedback=b.dataset.value;persist();render();break;case'begin':lastSampleAt=-Infinity;session={samples:[],post:state.pre,effort:0,note:'',id:crypto.randomUUID(),startedAt:new Date().toISOString(),plan:structuredClone(state.plan),counts:state.plan.map(()=>0),index:0,pre:state.pre,feedback:state.feedback,elapsed:0,tick:performance.now(),running:true};render();break;case'pause':if(!session)break;if(session.running)pauseSession();else{session.tick=performance.now();session.running=true}render();break;case'rep':if(session?.running){const i=session.index;session.counts[i]=Math.min(session.plan[i].reps,session.counts[i]+1);render()}break;case'undo':if(session?.running){session.counts[session.index]=Math.max(0,session.counts[session.index]-1);render()}break;case'next':if(!session)break;if(session.index===session.plan.length-1){finishDialog();break}if(session.counts[session.index]<session.plan[session.index].reps&&!confirm(t('remaining')))break;session.index++;render();break;case'end':finishDialog();break;case'camera':toggleCamera();break;case'camera-exit':exitCamera();break;case'voice-toggle':state.voiceEnabled=state.voiceEnabled===false;voiceGuide.setEnabled(state.voiceEnabled);persist();updateVoiceControls();break;case'voice-test':state.voiceEnabled=true;voiceGuide.setEnabled(true);voiceGuide.test();persist();updateVoiceControls();break;case'pose':togglePose();break;case'reset-pose':stopPose();togglePose();break;case'switch-camera':startCamera({facing:cameraFacing==='user'?'environment':'user'});break;case'camera-wide':if(cameraZoom)changeZoom(cameraZoom.min);break;case'delete-log':if(confirm(t('deleteConfirm'))){state.logs=state.logs.filter(l=>l.id!==b.dataset.id);persist();render()}break;case'export-csv':if(!state.logs.length){notify(t('noExport'));break}download(exportCsv(state.logs),'text/csv;charset=utf-8','csv');break;case'import-json':if(session){notify(t('planLocked'));break}document.querySelector('#backup-file').click();break;case'export-measurements':if(!state.logs.some(l=>l.samples?.length)){notify(t('noMeasurements'));break}download(exportMeasurements(state.logs),'text/csv;charset=utf-8','measurements.csv');break;case'export-json':saveDraft();download(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json','json');break}});
document.addEventListener('change',async e=>{if(e.target.dataset.change==='language'){state.lang=e.target.value;voiceGuide.languageChanged();persist();if(modal.open)modal.close();render()}if(e.target.dataset.change==='camera-view')cameraView=e.target.value;if(e.target.dataset.change==='camera-device')startCamera({deviceId:e.target.value});if(e.target.dataset.change==='camera-zoom')changeZoom(e.target.value);if(e.target.id==='backup-file'){const file=e.target.files?.[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error();const raw=await file.text();if(session){notify(t('planLocked'));return}const result=mergeBackup(state,raw);if(!confirm(t('importConfirm')))return;const old=state;state=result.state;if(!persist()){state=old;return}render();notify(t('importSuccess'))}catch{notify(t('importError'))}finally{e.target.value=''}}});
document.addEventListener('input',e=>{const k=e.target.dataset.input;if(!k)return;if(k==='session-note'){if(session){session.note=e.target.value.slice(0,1000);saveDraft()}return}const value=Number(e.target.value),out=document.querySelector(`#${k}-value`);if(out)out.innerHTML=`${value}<small> / 10</small>`;if(k==='pre'){state.pre=value;persist()}if(session&&['post','effort'].includes(k)){session[k]=value;saveDraft()}});
document.addEventListener('submit',e=>{if(e.target.id==='plan-form'){e.preventDefault();const f=new FormData(e.target),plan=[];for(let id=0;id<8;id++)if(f.has(`move-${id}`))plan.push({id,reps:Number(f.get(`reps-${id}`))});if(!validatePlan(plan)){document.querySelector('#plan-error').textContent=t(plan.length?'invalidReps':'needMove');return}state.plan=plan;state.custom=true;persist();modal.close();render();notify(t('saved'))}if(e.target.id==='session-form'){e.preventDefault();if(!session)return;const s=session,form=e.target,done=completion(s.counts,s.plan),log={id:s.id,startedAt:s.startedAt,endedAt:new Date().toISOString(),seconds:seconds(),plan:s.plan,counts:s.counts,pre:s.pre,post:Number(form.querySelector('#post').value),effort:Number(form.querySelector('#effort').value),note:form.querySelector('#session-note').value.trim(),feedback:s.feedback,aiFeedbackDelivered:false,appVersion:APP_VERSION,measurementMethod:MEASUREMENT_METHOD,samples:s.samples||[],completion:done,status:done===100?'completed':'stopped'};state.logs.push(log);const oldDraft=state.draft;state.draft=null;if(!persist()){state.logs.pop();state.draft=oldDraft;return}session=null;modal.close();view='records';render();notify(t('sessionSaved'))}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action]'))saveDraft()});
document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseSession();stopCamera()}else render()});
window.addEventListener('popstate',()=>{if(view==='camera'){cameraHistory=false;pauseSession();stopCamera();view='train';render()}});
window.addEventListener('pagehide',()=>{pauseSession();saveDraft();stopCamera()});
window.addEventListener('beforeunload',e=>{pauseSession();stopCamera();if(!saveDraft()&&session){e.preventDefault();e.returnValue=''}});
setInterval(()=>{const el=document.querySelector('#timer');if(el)el.textContent=time(seconds());if(session?.running&&seconds()>=86400){pauseSession();stopCamera();render()}},500);
setInterval(()=>{if(session)saveDraft()},5000);
render();
if(session)notify(t('draftRestored'));
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
